@Service @Transactional
public class TicketService {
 // Support staff of the Ticketing app (CLIENT users: CUSTOMER accounts see their customer's tickets, legacy ones their own tickets)
 private static final List<Role> SUPPORT_ROLES=List.of(Role.SALES_MANAGER_LEAD,Role.H24,Role.H24_LEAD);
 public List<UserSummary> agents(){AppUser a=current();Scope s=scope(a);if(!s.manager||s.organisationId==null)throw forbidden();return users.findByOrganisation_IdAndRoleInAndActiveTrueOrderByFullNameAsc(s.organisationId,SUPPORT_ROLES).stream().map(this::user).toList();}
 private final TicketRepository tickets; private final TicketMessageRepository messages; private final TicketActivityRepository activities; private final TicketAttachmentRepository attachments; private final TicketReadStateRepository readStates; private final UserRepository users; private final OrganisationRepository organisations; private final SecurityUtils security; private final TicketStatusService statuses; private final TicketCustomerService customers; private final TicketSettingsService settings; private final TicketAnalyticsService analytics; private final TicketNotifier notifier; private final TicketConfigService config;
 public TicketService(TicketRepository tickets,TicketMessageRepository messages,TicketActivityRepository activities,TicketAttachmentRepository attachments,TicketReadStateRepository readStates,UserRepository users,OrganisationRepository organisations,SecurityUtils security,TicketStatusService statuses,TicketCustomerService customers,TicketSettingsService settings,TicketAnalyticsService analytics,TicketNotifier notifier,TicketConfigService config){this.config=config;this.notifier=notifier;this.customers=customers;this.settings=settings;this.analytics=analytics;this.tickets=tickets;this.messages=messages;this.activities=activities;this.attachments=attachments;this.readStates=readStates;this.users=users;this.organisations=organisations;this.security=security;this.statuses=statuses;}
 public Page<TicketSummary> list(String search,Long statusId,String status,TicketPriority priority,String category,Long organisationId,Long assigneeId,Long creatorId,Long customerId,Instant from,Instant to,Pageable pageable){ AppUser actor=current(); Scope s=scope(actor); ensureTicketRole(s); if(organisationId!=null&&!s.platform&& !organisationId.equals(s.organisationId)) throw forbidden(); return tickets.search(s.platform,organisationId!=null?organisationId:s.organisationId,s.client,actor.getId(),s.customerId,pattern(search),statusId,status==null||status.isBlank()?null:status.trim().toUpperCase(),priority,category==null||category.isBlank()?null:category.trim().toUpperCase(),assigneeId,creatorId,customerId,from==null?Instant.EPOCH:from,to==null?Instant.parse("9999-12-31T23:59:59Z"):to,pageable).map(t->summary(t,actor)); }
 public TicketDetails get(Long id){ AppUser actor=current(); Ticket t=accessible(id,actor); markRead(t,actor); return details(t,actor); }
 public TicketDetails create(CreateTicketRequest request){ AppUser actor=current(); Scope s=scope(actor); ensureTicketRole(s); Organisation org=resolveOrganisation(request.organisationId(),s); if(s.client && request.organisationId()!=null&&!request.organisationId().equals(s.organisationId))throw forbidden(); AppUser client=s.client?actor:resolveClient(request.clientUserId(),org); Ticket t=new Ticket(); boolean customerOfClient=s.client||(client!=null&&client.isCustomerUser()); /* tickets of a CUSTOMER account always go to its customer */ applyContext(t,customerOfClient?null:request.customerId(),customerOfClient?null:request.customerName(),client,new ProjectInput(request.projectId(),request.projectName(),request.projectNumber(),request.projectYear()),request.equipmentId(),org.getId()); if(!s.client&&request.assigneeId()!=null)t.setAssignedSalesManager(supportUser(request.assigneeId(),org.getId()));t.setTicketNumber(nextNumber());t.setSubject(trim(request.subject()));t.setDescription(trim(request.description()));t.setOrganisation(org);t.setStatus(statuses.defaultStatus(org));t.setCreatedByUser(actor);t.setClientUser(client);t.setCategory(config.requireCategory(org.getId(),request.category()));t.setPriority(request.priority());t.setContactName(blankToNull(request.contactName()));t.setContactEmail(blankToNull(request.contactEmail()));t.setContactPhone(blankToNull(request.contactPhone()));t.setOrigin(request.origin()==null?TicketOrigin.WEB:request.origin());t.setSite(blankToNull(request.site()));t=tickets.save(t); activity(t,actor,TicketActivityType.CREATED,null,null,"Ticket created"); if(t.getAssignedSalesManager()!=null){activity(t,actor,TicketActivityType.ASSIGNED,null,t.getAssignedSalesManager().getFullName(),"H24 agent assigned","assignee");notifier.notify(t,t.getAssignedSalesManager(),actor,"assigned to you",t.getSubject(),"INFO");} if(request.initialMessage()!=null&&!request.initialMessage().isBlank()) addMessage(t.getId(),new MessageRequest(request.initialMessage(),false)); return details(t,actor); }
 public TicketDetails update(Long id,UpdateTicketRequest r){AppUser a=current(); Ticket t=manageable(id,a); version(t,r.version()); if(r.subject()!=null)t.setSubject(trim(r.subject())); if(r.description()!=null)t.setDescription(trim(r.description())); if(r.category()!=null&&!r.category().isBlank()){String cat=config.requireCategory(t.getOrganisation().getId(),r.category());if(!cat.equals(t.getCategory())){activity(t,a,TicketActivityType.UPDATED,t.getCategory(),cat,"Category changed to "+cat,"category");t.setCategory(cat);}} if(r.origin()!=null&&r.origin()!=t.getOrigin()){activity(t,a,TicketActivityType.UPDATED,t.getOrigin().name(),r.origin().name(),"Origin changed to "+r.origin(),"origin");t.setOrigin(r.origin());} if(r.site()!=null)t.setSite(blankToNull(r.site())); if(r.subject()!=null||r.description()!=null)activity(t,a,TicketActivityType.UPDATED,null,null,"Ticket information updated");return details(t,a);}
 // statusId (or status code): any active status of the ticket organisation (Ticketing settings > Statuses)
 public TicketDetails changeStatus(Long id,StatusRequest r){AppUser a=current();Ticket t=manageable(id,a);version(t,r.version());TicketStatus target=statuses.requireAssignable(t.getOrganisation(),r.statusId(),r.status());move(t,a,target,null,null);return details(t,a);}
 // Moves a ticket to a status. Entering a closed status stamps resolvedAt; the final close status (see TicketStatusService.closeTarget) also stamps closedAt; leaving the closed statuses clears closedAt.
 private void move(Ticket t,AppUser a,TicketStatus target,TicketActivityType type,String description){TicketStatus old=t.getStatus();if(old!=null&&old.getId().equals(target.getId()))return;boolean wasClosed=t.isClosed();boolean finalClose=target.isClosed()&&target.getId().equals(statuses.closeTarget(t.getOrganisation()).getId());t.setStatus(target);Instant now=Instant.now();if(target.isClosed()&&!wasClosed)t.setResolvedAt(now);if(finalClose){if(t.getClosedAt()==null)t.setClosedAt(now);}else t.setClosedAt(null);TicketActivityType kind=type!=null?type:target.isClosed()?(finalClose?TicketActivityType.CLOSED:TicketActivityType.RESOLVED):wasClosed?TicketActivityType.REOPENED:TicketActivityType.STATUS_CHANGED;activity(t,a,kind,old==null?null:old.getName(),target.getName(),description!=null?description:"Status changed to "+target.getName());notifier.notify(t,t.getClientUser(),a,"status is now "+target.getName(),t.getSubject(),"INFO");}
 // Contact person at the customer (name, email, phone)
 public TicketDetails updateContact(Long id,ContactPersonRequest r){AppUser a=current();Ticket t=manageable(id,a);version(t,r.version());if(isFinished(t))throw new TicketConflictException("Finished tickets cannot be changed.");String before=contactLabel(t);t.setContactName(blankToNull(r.contactName()));t.setContactEmail(blankToNull(r.contactEmail()));t.setContactPhone(blankToNull(r.contactPhone()));String after=contactLabel(t);if(!before.equals(after))activity(t,a,TicketActivityType.UPDATED,before,after,"Contact person changed","contact");return details(t,a);}
 /** Deletes a ticket with its messages, activities, read states and attachment records (support leads only). Returns the stored attachment files to remove. */
 public List<String> delete(Long id){AppUser a=current();Ticket t=manageable(id,a);if(!a.hasAnyRole(TicketSettingsService.LEAD_ROLES)&&!platform(a))throw forbidden();List<String> files=attachments.findByTicket_IdOrderByUploadedAtAsc(id).stream().map(TicketAttachment::getStoragePath).toList();tickets.deleteReadStates(id);tickets.deleteActivities(id);tickets.deleteAttachments(id);tickets.deleteMessages(id);tickets.delete(t);tickets.flush();return files;}
 /** Dashboard of the client portal: statistics of the current client's own tickets only (client + organisation filtered in the query). */
 public ClientDashboard clientDashboard(){AppUser a=current();Scope s=scope(a);if(!s.client||s.organisationId==null)throw forbidden();List<Ticket> mine=tickets.search(false,s.organisationId,true,a.getId(),s.customerId,null,null,null,null,null,null,null,null,Instant.EPOCH,Instant.parse("9999-12-31T23:59:59Z"),Pageable.unpaged()).getContent();double[] sla=analytics.overdueAndAverageResolution(mine,s.organisationId);Map<String,Long> byStatus=new LinkedHashMap<>();statuses.statusesOf(a.getOrganisation()).forEach(st->{long n=mine.stream().filter(t->t.getStatus()!=null&&st.getId().equals(t.getStatus().getId())).count();if(n>0)byStatus.put(st.getCode(),n);});java.time.format.DateTimeFormatter month=java.time.format.DateTimeFormatter.ofPattern("yyyy-MM").withZone(ZoneOffset.UTC);YearMonth now=YearMonth.now(ZoneOffset.UTC);Map<String,Long> months=new LinkedHashMap<>();for(int i=11;i>=0;i--)months.put(now.minusMonths(i).toString(),0L);mine.forEach(t->months.computeIfPresent(month.format(t.getCreatedAt()),(k,v)->v+1));long open=mine.stream().filter(t->!t.isClosed()&&t.getStatus()!=null&&t.getStatus().isDefault()).count();long progress=mine.stream().filter(t->!t.isClosed()&&(t.getStatus()==null||!t.getStatus().isDefault())).count();long closed=mine.stream().filter(Ticket::isClosed).count();List<TicketSummary> recent=mine.stream().sorted(Comparator.comparing(Ticket::getUpdatedAt,Comparator.nullsLast(Comparator.reverseOrder()))).limit(5).map(t->summary(t,a)).toList();return new ClientDashboard(mine.size(),open,progress,closed,(long)sla[0],Math.round(sla[1]*10)/10.0,breakdown(byStatus),breakdown(mine.stream().collect(Collectors.groupingBy(t->t.getPriority().name(),LinkedHashMap::new,Collectors.counting()))),breakdown(mine.stream().collect(Collectors.groupingBy(Ticket::getCategory,LinkedHashMap::new,Collectors.counting()))),breakdown(months),recent);}
 private static List<Breakdown> breakdown(Map<String,Long> m){return m.entrySet().stream().map(e->new Breakdown(e.getKey(),e.getValue())).toList();}
 private static String contactLabel(Ticket t){return String.join(" / ",Objects.toString(t.getContactName(),"-"),Objects.toString(t.getContactEmail(),"-"),Objects.toString(t.getContactPhone(),"-"));}
 public TicketDetails changePriority(Long id,PriorityRequest r){AppUser a=current();Ticket t=manageable(id,a);version(t,r.version());TicketPriority old=t.getPriority();t.setPriority(r.priority());activity(t,a,TicketActivityType.PRIORITY_CHANGED,old.name(),r.priority().name(),"Priority changed to "+r.priority());return details(t,a);}
 public TicketDetails assign(Long id,AssignmentRequest r){AppUser a=current();Ticket t=manageable(id,a);version(t,r.version());AppUser assignee=r.assigneeId()==null?null:users.findByIdAndOrganisation_Id(r.assigneeId(),t.getOrganisation().getId()).orElseThrow(()->new ResponseStatusException(HttpStatus.BAD_REQUEST,"Assignee is outside the ticket organisation.")); if(assignee!=null&&(!isManager(assignee)||!assignee.isActive()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Assignee must be an active member of the support team.");String old=t.getAssignedSalesManager()==null?null:t.getAssignedSalesManager().getFullName();t.setAssignedSalesManager(assignee);activity(t,a,TicketActivityType.ASSIGNED,old,assignee==null?null:assignee.getFullName(),assignee==null?"H24 agent removed":"H24 agent assigned","assignee");notifier.notify(t,assignee,a,"assigned to you",t.getSubject(),"INFO");return details(t,a);}
 // L2 technician handling an escalated ticket; must be flagged as L2 in Settings > L2 technicians
 public TicketDetails assignL2(Long id,AssignmentRequest r){AppUser a=current();Ticket t=manageable(id,a);version(t,r.version());if(isFinished(t))throw new TicketConflictException("Finished tickets cannot be reassigned.");AppUser tech=r.assigneeId()==null?null:users.findByIdAndOrganisation_Id(r.assigneeId(),t.getOrganisation().getId()).orElseThrow(()->new ResponseStatusException(HttpStatus.BAD_REQUEST,"Technician is outside the ticket organisation."));if(tech!=null&&(!tech.isActive()||!settings.isL2Technician(tech)))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"The selected user is not an L2 technician.");String old=t.getL2Technician()==null?null:t.getL2Technician().getFullName();t.setL2Technician(tech);activity(t,a,TicketActivityType.ASSIGNED,old,tech==null?null:tech.getFullName(),tech==null?"L2 technician removed":"L2 technician assigned","l2Technician");notifier.notify(t,tech,a,"escalated to you (L2)",t.getSubject(),"WARNING");return details(t,a);}
 // Customer, site, project and equipment of a ticket
 public TicketDetails updateContext(Long id,TicketContextRequest r){AppUser a=current();Ticket t=manageable(id,a);version(t,r.version());if(isFinished(t))throw new TicketConflictException("Finished tickets cannot be changed.");String before=contextLabel(t);applyContext(t,r.customerId(),r.customerName(),t.getClientUser(),new ProjectInput(r.projectId(),r.projectName(),r.projectNumber(),r.projectYear()),r.equipmentId(),t.getOrganisation().getId());t.setSite(blankToNull(r.site()));String after=contextLabel(t);if(!before.equals(after))activity(t,a,TicketActivityType.UPDATED,before,after,"Customer, site, project or equipment changed","context");return details(t,a);}
 // Problem statement: observed problem, root cause and solution. Support staff only.
 public TicketDetails updateProblemStatement(Long id,ProblemStatementRequest r){AppUser a=current();Ticket t=manageable(id,a);version(t,r.version());if(isFinished(t))throw new TicketConflictException("Closed tickets cannot be changed.");t.setRcaProblem(blankToNull(r.problem()));t.setRcaCause(blankToNull(r.cause()));t.setRcaSolution(blankToNull(r.solution()));activity(t,a,TicketActivityType.UPDATED,null,null,"Problem statement updated","problemStatement");return details(t,a);}
 // Escalation raises the level and, when the organisation kept an active ESCALATED status, moves the ticket to it
 public TicketDetails escalate(Long id,Long version){AppUser a=current();Ticket t=manageable(id,a);version(t,version);if(t.isClosed())throw new TicketConflictException("Closed tickets cannot be escalated.");TicketStatus old=t.getStatus();t.setEscalationLevel(t.getEscalationLevel()+1);statuses.activeByCode(t.getOrganisation(),TicketStatusService.ESCALATED).filter(st->!st.isClosed()).ifPresent(t::setStatus);activity(t,a,TicketActivityType.ESCALATED,old==null?null:old.getName(),t.getStatus()==null?null:t.getStatus().getName(),"Ticket escalated to level "+t.getEscalationLevel());return details(t,a);}
 public TicketDetails resolve(Long id,Long version){AppUser a=current();Ticket t=manageable(id,a);version(t,version);move(t,a,statuses.resolveTarget(t.getOrganisation()),null,null);return details(t,a);}
 // Clients may reopen or close a ticket that is in a closed status but not finally closed yet (closedAt empty)
 public TicketDetails reopen(Long id,Long version){AppUser a=current();Ticket t=accessible(id,a);boolean client=scope(a).client;if(client&&!clientMayAct(t))throw forbidden();if(!t.isClosed())throw new TicketConflictException("Only closed tickets can be reopened.");version(t,version);move(t,a,statuses.reopenTarget(t.getOrganisation()),TicketActivityType.REOPENED,client?"Ticket reopened by client":null);return details(t,a);}
 public TicketDetails close(Long id,Long version){AppUser a=current();Ticket t=accessible(id,a);boolean client=scope(a).client;if(client&&!clientMayAct(t))throw new TicketConflictException("Only resolved tickets can be closed by a client.");version(t,version);move(t,a,statuses.closeTarget(t.getOrganisation()),TicketActivityType.CLOSED,client?"Ticket closed by client":null);return details(t,a);}
 private static boolean clientMayAct(Ticket t){return t.isClosed()&&t.getClosedAt()==null;}
 public TicketMessageDto addMessage(Long id,MessageRequest r){AppUser a=current();Ticket t=accessible(id,a);if(scope(a).client&&r.internalNote())throw forbidden();if(r.message()==null||r.message().trim().isEmpty())throw new IllegalArgumentException("Message cannot be empty.");TicketMessage m=new TicketMessage();m.setTicket(t);m.setSender(a);m.setMessage(trim(r.message()));m.setInternalNote(r.internalNote());m=messages.save(m);t.setLastMessageAt(m.getCreatedAt());activity(t,a,TicketActivityType.MESSAGE_ADDED,null,null,r.internalNote()?"Internal note added":"Message added");notifyMessage(t,a,r);return message(m);}
 public TicketMessageDto addMessageForUser(Long id,Long userId,MessageRequest r){AppUser a=users.findById(userId).orElseThrow(()->new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Current account no longer exists."));Ticket t=accessible(id,a);if(scope(a).client&&r.internalNote())throw forbidden();if(r.message()==null||r.message().trim().isEmpty())throw new IllegalArgumentException("Message cannot be empty.");TicketMessage m=new TicketMessage();m.setTicket(t);m.setSender(a);m.setMessage(trim(r.message()));m.setInternalNote(r.internalNote());m=messages.save(m);t.setLastMessageAt(m.getCreatedAt());activity(t,a,TicketActivityType.MESSAGE_ADDED,null,null,r.internalNote()?"Internal note added":"Message added");notifyMessage(t,a,r);return message(m);}
 public List<TicketMessageDto> messages(Long id){AppUser a=current();Ticket t=accessible(id,a);return (scope(a).client?messages.findByTicket_IdAndInternalNoteFalseOrderByCreatedAtAsc(id):messages.findByTicket_IdOrderByCreatedAtAsc(id)).stream().filter(m->!m.isDeleted()).map(this::message).toList();}
 public List<TicketActivityDto> activity(Long id){AppUser a=current();accessible(id,a);return activities.findByTicket_IdOrderByCreatedAtAsc(id).stream().map(this::activityDto).toList();}
 public TicketStatistics stats(){AppUser a=current();Scope s=scope(a);ensureTicketRole(s);double[] sla=s.organisationId==null?new double[]{0,0}:analytics.overdueAndAverageResolution(tickets.search(s.platform,s.organisationId,s.client,a.getId(),s.customerId,null,null,null,null,null,null,null,null,Instant.EPOCH,Instant.parse("9999-12-31T23:59:59Z"),Pageable.unpaged()).getContent(),s.organisationId);Instant today=LocalDate.now(ZoneOffset.UTC).atStartOfDay(ZoneOffset.UTC).toInstant();long open=0,closed=0;Map<String,Long> byStatus=new LinkedHashMap<>();for(Object[] row:tickets.countVisibleByStatus(s.platform,s.organisationId,s.client,a.getId(),s.customerId)){long n=((Number)row[2]).longValue();byStatus.merge((String)row[0],n,Long::sum);if(Boolean.TRUE.equals(row[1]))closed+=n;else open+=n;}return new TicketStatistics(open,closed,tickets.countVisibleCreatedSince(s.platform,s.organisationId,s.client,a.getId(),s.customerId,today),(long)sla[0],Math.round(sla[1]*10)/10.0,breakdown(byStatus));}
 public boolean canAccess(Long ticketId,Long userId){try{AppUser a=users.findById(userId).orElse(null);if(a==null)return false;accessible(ticketId,a);return true;}catch(RuntimeException ex){return false;}}
 public Ticket requireAccessible(Long id){return accessible(id,current());} public AppUser currentUser(){return current();} public boolean mayManageCurrent(){return scope(current()).manager;}
 private Ticket accessible(Long id,AppUser a){Ticket t=tickets.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Ticket not found."));Scope s=scope(a);ensureTicketRole(s);if(!s.platform&&!Objects.equals(t.getOrganisation().getId(),s.organisationId))throw forbidden();if(s.client&&s.customerId!=null&&!Objects.equals(t.getCustomer()==null?null:t.getCustomer().getId(),s.customerId))throw forbidden();
  if(s.client&&s.customerId==null&&!Objects.equals(t.getClientUser()==null?null:t.getClientUser().getId(),a.getId())&&!Objects.equals(t.getCreatedByUser().getId(),a.getId()))throw forbidden();return t;} private Ticket manageable(Long id,AppUser a){if(!scope(a).manager)throw forbidden();return accessible(id,a);} private AppUser current(){Long id=security.getCurrentUserId();return users.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Current account no longer exists."));} private Scope scope(AppUser a){boolean manager=isManager(a);boolean client=a.hasRole(Role.CLIENT)&&!manager;
  // CUSTOMER accounts see every ticket of their customer; legacy CLIENT accounts (no customer link) only their own
  Long customerId=client&&a.isCustomerUser()&&a.getCustomer()!=null?a.getCustomer().getId():null;
  return new Scope(platform(a),client,manager,a.getOrganisation()==null?null:a.getOrganisation().getId(),customerId);} private void ensureTicketRole(Scope s){if(!s.client&&!s.manager)throw forbidden();} private boolean platform(AppUser a){return a.hasRole(Role.PLATFORM_OWNER);} private boolean isManager(AppUser a){return a.hasAnyRole(SUPPORT_ROLES);} private Organisation resolveOrganisation(Long requested,Scope s){Long id=requested==null?s.organisationId:requested;if(id==null)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"An organisation is required.");if(!s.platform&&!id.equals(s.organisationId))throw forbidden();return organisations.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.BAD_REQUEST,"Organisation not found."));} private AppUser resolveClient(Long id,Organisation org){if(id==null)return null;AppUser u=users.findByIdAndOrganisation_Id(id,org.getId()).orElseThrow(()->new ResponseStatusException(HttpStatus.BAD_REQUEST,"Client is outside the selected organisation."));if(!u.hasRole(Role.CLIENT))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Selected client must have CLIENT role.");return u;}
 private String nextNumber(){String prefix="TKT-"+Year.now(ZoneOffset.UTC)+"-";Ticket latest=tickets.findFirstByTicketNumberStartingWithOrderByTicketNumberDesc(prefix).orElse(null);int seq=latest==null?1:Integer.parseInt(latest.getTicketNumber().substring(prefix.length()))+1;return prefix+String.format("%06d",seq);} private void version(Ticket t,Long expected){if(expected==null||!Objects.equals(t.getVersion(),expected))throw new TicketConflictException("Ticket was updated by another user. Refresh and try again.");} private String pattern(String v){return v==null||v.isBlank()?null:"%"+v.trim().toLowerCase()+"%";} private String trim(String v){if(v==null||v.trim().isEmpty())throw new IllegalArgumentException("Value cannot be blank.");return v.trim();}private String blankToNull(String v){return v==null||v.trim().isEmpty()?null:v.trim();}private ResponseStatusException forbidden(){return new ResponseStatusException(HttpStatus.FORBIDDEN,"You do not have access to this ticket.");}
 private void activity(Ticket t,AppUser actor,TicketActivityType type,String old,String value,String description){activity(t,actor,type,old,value,description,null);} private void activity(Ticket t,AppUser actor,TicketActivityType type,String old,String value,String description,String field){TicketActivity h=new TicketActivity();h.setField(field);h.setTicket(t);h.setActor(actor);h.setActivityType(type);h.setPreviousValue(old);h.setNewValue(value);h.setDescription(description);activities.save(h);}
 private TicketSummary summary(Ticket t,AppUser a){return summary(t,a,sla(t));} private TicketSummary summary(Ticket t,AppUser a,PrioritySettingDto target){Instant read=readStates.findByTicket_IdAndUser_Id(t.getId(),a.getId()).map(TicketReadState::getLastReadAt).orElse(Instant.EPOCH);return new TicketSummary(t.getId(),t.getTicketNumber(),t.getSubject(),t.getOrganisation().getId(),t.getOrganisation().getName(),t.getStatus()==null?null:t.getStatus().getCode(),t.getPriority(),t.getCategory(),t.getSite(),user(t.getClientUser()),user(t.getAssignedSalesManager()),t.getCreatedAt(),t.getUpdatedAt(),t.getLastMessageAt(),messages.countByTicket_IdAndCreatedAtAfterAndSender_IdNot(t.getId(),read,a.getId()),customerRef(t),projectRef(t),user(t.getL2Technician()),TicketAnalyticsService.overdue(t,target,Instant.now()),t.getProjectNumber()!=null||t.getProject()==null?t.getProjectNumber():t.getProject().getCode(),t.getProjectYear()!=null||t.getProject()==null?t.getProjectYear():TicketCustomerService.projectYear(t.getProject()),TicketStatusService.ref(t.getStatus()));} private TicketDetails details(Ticket t,AppUser a){return new TicketDetails(summary(t,a),t.getDescription(),t.getOrigin(),t.getEscalationLevel(),t.getResolvedAt(),t.getClosedAt(),t.getVersion(),messages(t.getId()),activity(t.getId()),attachments.findByTicket_IdOrderByUploadedAtAsc(t.getId()).stream().map(this::attachment).toList(),scope(a).manager,clientMayAct(t)||scope(a).manager,t.getEquipment()==null?null:customers.equipment(t.getEquipment()),t.getRcaProblem(),t.getRcaCause(),t.getRcaSolution(),settings.languageOf(t.getClientUser()),new ContactPerson(t.getContactName(),t.getContactEmail(),t.getContactPhone()),scope(a).manager&&(a.hasAnyRole(TicketSettingsService.LEAD_ROLES)||platform(a)));} private UserSummary user(AppUser u){return u==null?null:new UserSummary(u.getId(),u.getFullName(),u.getEmail(),u.getPrimaryRole().name());} private TicketMessageDto message(TicketMessage m){return new TicketMessageDto(m.getId(),m.getMessage(),m.getMessageType(),m.isInternalNote(),user(m.getSender()),m.getCreatedAt(),m.getEditedAt());}private TicketActivityDto activityDto(TicketActivity h){return new TicketActivityDto(h.getId(),h.getActivityType(),h.getPreviousValue(),h.getNewValue(),h.getDescription(),user(h.getActor()),h.getCreatedAt(),h.getField());}private TicketAttachmentDto attachment(TicketAttachment x){return new TicketAttachmentDto(x.getId(),x.getOriginalFileName(),x.getContentType(),x.getFileSize(),user(x.getUploadedBy()),x.getUploadedAt());}private void markRead(Ticket t,AppUser a){TicketReadState s=readStates.findByTicket_IdAndUser_Id(t.getId(),a.getId()).orElseGet(TicketReadState::new);s.setTicket(t);s.setUser(a);s.setLastReadAt(Instant.now());readStates.save(s);} private void notifyMessage(Ticket t,AppUser sender,MessageRequest r){String preview=r.message().length()>140?r.message().substring(0,140)+"…":r.message();boolean fromClient=t.getClientUser()!=null&&Objects.equals(t.getClientUser().getId(),sender.getId());if(fromClient){notifier.notify(t,t.getAssignedSalesManager(),sender,"new message from "+sender.getFullName(),preview,"INFO");notifier.notify(t,t.getL2Technician(),sender,"new message from "+sender.getFullName(),preview,"INFO");}else if(!r.internalNote())notifier.notify(t,t.getClientUser(),sender,"new reply from support",preview,"INFO");}
 private PrioritySettingDto sla(Ticket t){return settings.priorities(t.getOrganisation().getId()).get(t.getPriority());}
 private boolean isFinished(Ticket t){return t.isClosed();}
 private AppUser supportUser(Long id,Long org){AppUser u=users.findByIdAndOrganisation_Id(id,org).orElseThrow(()->new ResponseStatusException(HttpStatus.BAD_REQUEST,"Agent is outside the organisation."));if(!isManager(u)||!u.isActive())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Assignee must be an active member of the support team.");return u;}
 // Customer from the request, else the customer the client account is linked to; project and equipment must belong to that customer
 // Customer: a Projectum customer (customerId), else a manual name, else the customer the client account is linked to.
 // Project: a Projectum project (projectId), else a manual name / number / year. Linked values are copied onto the ticket
 // when the link changes, so the ticket keeps what was saved even if the Projectum record changes later.
 // Equipment must belong to the registered customer.
 private void applyContext(Ticket t,Long customerId,String customerName,AppUser client,ProjectInput project,Long equipmentId,Long org){
  String manualCustomer=blankToNull(customerName);
  com.ercopac.ercopac_tracker.admin.domain.Customer c=customerId!=null?customers.requireCustomer(customerId,org):manualCustomer!=null?customers.findOrCreateManualCustomer(manualCustomer,org):customers.customerOfClient(client);
  Long previousCustomer=t.getCustomer()==null?null:t.getCustomer().getId();
  t.setCustomer(c);
  if(c==null)t.setCustomerName(manualCustomer);else if(manualCustomer!=null&&customerId==null)t.setCustomerName(c.getName());else if(!c.getId().equals(previousCustomer)||t.getCustomerName()==null)t.setCustomerName(c.getName());
  if(project.id()!=null){
   com.ercopac.ercopac_tracker.projects.domain.Project p=customers.requireProject(project.id(),c,org);
   boolean relinked=t.getProject()==null||!p.getId().equals(t.getProject().getId())||t.getProjectName()==null;
   t.setProject(p);
   if(relinked){t.setProjectName(p.getName());t.setProjectNumber(p.getCode());t.setProjectYear(TicketCustomerService.projectYear(p));}
  }else{
   String name=blankToNull(project.name());String number=blankToNull(project.number());
   if(name==null&&(number!=null||project.year()!=null))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"A manual project needs a name.");
   t.setProject(null);t.setProjectName(name);t.setProjectNumber(name==null?null:number);t.setProjectYear(name==null?null:project.year());
  }
  t.setEquipment(equipmentId==null?null:customers.requireEquipment(equipmentId,c,org));
 }
 private record ProjectInput(Long id,String name,String number,Integer year){}
 // Name saved on the ticket; tickets created before the snapshot columns fall back to the linked record
 private static String customerName(Ticket t){return t.getCustomerName()!=null?t.getCustomerName():t.getCustomer()==null?null:t.getCustomer().getName();}
 private static String projectName(Ticket t){return t.getProjectName()!=null?t.getProjectName():t.getProject()==null?null:t.getProject().getName();}
 private static Ref customerRef(Ticket t){String name=customerName(t);return name==null?null:new Ref(t.getCustomer()==null?null:t.getCustomer().getId(),name);}
 private static Ref projectRef(Ticket t){String name=projectName(t);return name==null?null:new Ref(t.getProject()==null?null:t.getProject().getId(),name);}
 private String contextLabel(Ticket t){return String.join(" / ",Objects.toString(customerName(t),"-"),t.getSite()==null?"-":t.getSite(),Objects.toString(projectName(t),"-"),t.getEquipment()==null?"-":t.getEquipment().getName());}
 // customerId: the customer a CUSTOMER account is limited to (null for staff and legacy CLIENT accounts)
 private record Scope(boolean platform,boolean client,boolean manager,Long organisationId,Long customerId){}
}
